import{_ as s,a0 as i,w as o,s as p,ao as d,I as n,x as e,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"LNAV：基於 Ncurses 的日誌文件閲讀器 | LCTT x X-CMD","titleTemplate":false,"description":"LNAV：基於 Ncurses 的日誌文件閲讀器 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LNAV：基於 Ncurses 的日誌文件閲讀器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LNAV：基於 Ncurses 的日誌文件閲讀器 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151123 LNAV--Ncurses based log file viewer","title":"LNAV：基於 Ncurses 的日誌文件閲讀器","tag":"201512","desc":""},"relativePath":"201512/20151123 LNAV--Ncurses based log file viewer.md","filePath":"[post].md"}'),u={name:"201512/20151123 LNAV--Ncurses based log file viewer.md"};function h(b,a,m,f,c,v){const r=i("Link");return o(),p("div",null,[a[13]||(a[13]=d(`<h1 id="lnav-基於-ncurses-的日誌文件閲讀器" tabindex="-1">LNAV：基於 Ncurses 的日誌文件閲讀器 <a class="header-anchor" href="#lnav-基於-ncurses-的日誌文件閲讀器" aria-label="Permalink to “LNAV：基於 Ncurses 的日誌文件閲讀器”">​</a></h1><p>日誌文件導航器（Logfile Navigator，簡稱 lnav），是一個基於 curses 的，用於查看和分析日誌文件的工具。和文本閲讀器/編輯器相比， lnav 的好處是它充分利用了可以從日誌文件中獲取的語義信息，例如時間戳和日誌等級。利用這些額外的語義信息， lnav 可以處理像這樣的事情：來自不同文件的交錯的信息；按照時間生成信息直方圖；支持在文件中導航的快捷鍵。它希望使用這些功能可以使得用户可以快速有效地定位和解決問題。</p><h3 id="lnav-功能" tabindex="-1">lnav 功能 <a class="header-anchor" href="#lnav-功能" aria-label="Permalink to “lnav 功能”">​</a></h3><h4 id="支持以下日誌文件格式" tabindex="-1">支持以下日誌文件格式： <a class="header-anchor" href="#支持以下日誌文件格式" aria-label="Permalink to “支持以下日誌文件格式：”">​</a></h4><p>Syslog、Apache 訪問日誌、strace、tcsh 歷史以及常見的帶時間戳的日誌文件。讀入文件的時候回自動檢測文件格式。</p><h4 id="直方圖視圖" tabindex="-1">直方圖視圖： <a class="header-anchor" href="#直方圖視圖" aria-label="Permalink to “直方圖視圖：”">​</a></h4><p>以時間區劃來顯示日誌信息數量。這對於大概瞭解在一長段時間內發生了什麼非常有用。</p><h4 id="過濾器" tabindex="-1">過濾器： <a class="header-anchor" href="#過濾器" aria-label="Permalink to “過濾器：”">​</a></h4><p>只顯示那些匹配或不匹配一些正則表達式的行。對於移除大量你不感興趣的日誌行非常有用。</p><h4 id="即時操作" tabindex="-1">即時操作： <a class="header-anchor" href="#即時操作" aria-label="Permalink to “即時操作：”">​</a></h4><p>在你輸入到時候會同時完成檢索；當添加了新日誌行的時候會自動加載和搜索；加載行的時候會應用過濾器；另外，還會在你輸入 SQL 查詢的時候檢查其正確性。</p><h4 id="自動顯示後文" tabindex="-1">自動顯示後文： <a class="header-anchor" href="#自動顯示後文" aria-label="Permalink to “自動顯示後文：”">​</a></h4><p>日誌文件視圖會自動往下滾動到新添加到文件中的行。只需要向上滾動就可以鎖定當前視圖，然後向下滾動到底部恢復顯示後文。</p><h4 id="按照日期順序排序行" tabindex="-1">按照日期順序排序行： <a class="header-anchor" href="#按照日期順序排序行" aria-label="Permalink to “按照日期順序排序行：”">​</a></h4><p>從所有文件中加載的日誌行會按照日期進行排序。使得你不需要手動從不同文件中收集日誌信息。</p><h4 id="語法高亮" tabindex="-1">語法高亮： <a class="header-anchor" href="#語法高亮" aria-label="Permalink to “語法高亮：”">​</a></h4><p>錯誤和警告會用紅色和黃色顯示。高亮還可用於： SQL 關鍵字、XML 標籤、Java 文件行號和括起來的字符串。</p><h4 id="導航" tabindex="-1">導航： <a class="header-anchor" href="#導航" aria-label="Permalink to “導航：”">​</a></h4><p>有快捷鍵用於跳轉到下一個或上一個錯誤或警告，按照指定的時間向後或向前翻頁。</p><h4 id="用-sql-查詢日誌" tabindex="-1">用 SQL 查詢日誌： <a class="header-anchor" href="#用-sql-查詢日誌" aria-label="Permalink to “用 SQL 查詢日誌：”">​</a></h4><p>每個日誌文件行都相當於資料庫中的一行，可以使用 SQL 進行查詢。可以使用的列取決於查看的日誌文件類型。</p><h4 id="命令和搜索歷史" tabindex="-1">命令和搜索歷史：　#### <a class="header-anchor" href="#命令和搜索歷史" aria-label="Permalink to “命令和搜索歷史：　####”">​</a></h4><p>會自動保存你之前輸入的命令和搜素，因此你可以在會話之間使用它們。</p><p>####　壓縮文件： ####</p><p>會實時自動檢測和解壓壓縮的日誌文件。</p><h3 id="在-ubuntu-15-10-上安裝-lnav" tabindex="-1">在 ubuntu 15.10 上安裝 lnav <a class="header-anchor" href="#在-ubuntu-15-10-上安裝-lnav" aria-label="Permalink to “在 ubuntu 15.10 上安裝 lnav”">​</a></h3><p>打開終端運行下面的命令</p><pre><code>sudo apt-get install lnav
</code></pre><h3 id="使用-lnav" tabindex="-1">使用 lnav <a class="header-anchor" href="#使用-lnav" aria-label="Permalink to “使用 lnav”">​</a></h3><p>如果你想使用 lnav 查看日誌，你可以使用下面的命令，默認它會顯示 syslogs</p><pre><code>lnav
</code></pre><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/11/51.png" alt=""></p><p>如果你想查看特定的日誌，那麼需要指定路徑。如果你想看 CPU 日誌，在你的終端裏運行下面的命令</p><pre><code>lnav /var/log/cups
</code></pre><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/11/6.png" alt=""></p><hr>`,36)),n("p",null,[a[1]||(a[1]=e("via: ",-1)),t(r,{href:"http://www.ubuntugeek.com/lnav-ncurses-based-log-file-viewer.html"},{default:l(()=>[...a[0]||(a[0]=[e("http://www.ubuntugeek.com/lnav-ncurses-based-log-file-viewer.html",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=e("作者：",-1)),t(r,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:l(()=>[...a[2]||(a[2]=[e("ruchi",-1)])]),_:1}),a[6]||(a[6]=e(" 譯者：",-1)),t(r,{href:"http://mutouxiaogui.cn/blog/"},{default:l(()=>[...a[3]||(a[3]=[e("ictlyh",-1)])]),_:1}),a[7]||(a[7]=e(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:l(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=e("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[8]||(a[8]=[e("LCTT",-1)])]),_:1}),a[11]||(a[11]=e(" 原創編譯，",-1)),t(r,{href:"https://linux.cn/"},{default:l(()=>[...a[9]||(a[9]=[e("Linux中國",-1)])]),_:1}),a[12]||(a[12]=e(" 榮譽推出",-1))])])}const L=s(u,[["render",h]]);export{N as __pageData,L as default};
